 @EnvironmentObject var store:AppStore;@Environment(\.dismiss) var dismiss;@State private var photos:[String:UIImage]=[:];@State private var artifact:PosterArtifact?;@State private var shareURL:URL?;@State private var exporting=false
 func render(){guard let event=store.event else{return};artifact=PosterRenderer.make(event:event,picks:store.picks,username:store.profile?.username,photos:photos)}
