atMap(URL.init(string:)),url.scheme=="https",["a.espncdn.com","ufc.com","www.ufc.com","gidstats.com","gidstats.ru","d33t2v9cbr12gb.cloudfront.net"].contains(url.host ?? "") else{continue};if let (data,response)=try? await URLSession.shared.data(from:url),let http=response as? HTTPURLResponse,http.statusCode==200,data.count<3_000_000,let image=UIImage(data:data){photos[fighter.id]=image}};render()}}}
